package org.rhetos.arn

import kotlinx.browser.document
import kotlinx.coroutines.MainScope
import kotlinx.coroutines.launch
import kotlinx.browser.window
import kotlinx.coroutines.await
import kotlinx.serialization.json.Json
import org.rhetos.arn.json.Picture
import org.w3c.dom.HTMLAnchorElement

class Pictures {
    val scope = MainScope()
    fun main() {
        scope.launch {
            val response = window.fetch("jsonData/pictures.json").await()
            val json = response.text().await()
            val picts = Json.decodeFromString<List<Picture>>(json)

            val container = document.getElementById("pictures")!!

            val title = document.createElement("h1")
            title.textContent = "Galerie"

            container.appendChild(title)

            for (picture in picts) {
                val element = document.createElement("a") as HTMLAnchorElement
                element.className = "element"

                val pict = document.createElement("img")
                pict.className = "element-image"
                pict.setAttribute("src", picture.path)

                val namePict = document.createElement("p")
                namePict.textContent = picture.name

                element.appendChild(pict)
                element.appendChild(namePict)

                container.appendChild(element)
            }
        }
    }
}