package org.rhetos.arn

import kotlinx.browser.document
import kotlinx.browser.window
import kotlinx.coroutines.MainScope
import kotlinx.coroutines.await
import kotlinx.coroutines.launch
import kotlinx.serialization.json.Json
import org.rhetos.arn.json.News

class Article(private val id: Int) {

    private val scope = MainScope()

    fun main() {
        scope.launch {
            val response = window.fetch("jsonData/news.json").await()
            val json = response.text().await()

            val news = Json.decodeFromString<List<News>>(json)

            val article = news.find { it.id == id }

            if (article == null) {
                NotFound().main()
                return@launch
            }

            document.title = article.title

            val container = document.getElementById("article")!!

            val title = document.createElement("h1")
            title.textContent = article.title

            val description = document.createElement("h2")
            description.textContent = article.short

            val author = document.createElement("h5")
            author.textContent = "Article rédigé avec amour & savoir par " + article.author

            val subDescription = document.createElement("p")
            subDescription.textContent = article.long

            container.appendChild(title)
            container.appendChild(description)
            container.appendChild(author)
            container.appendChild(subDescription)
        }
    }
}