package org.rhetos.arn

import kotlinx.browser.document
import org.w3c.dom.HTMLAnchorElement

class Index {
    fun main() {
        val main = document.createElement("main")

        val titleSpacing = document.createElement("div")
        titleSpacing.className = "spacing"
        val title = document.createElement("h1")
        title.textContent = "Crête 2027"
        titleSpacing.appendChild(title)

        val subtitle = document.createElement("h2")
        subtitle.textContent = "Quand Herso & Nissos se rencontrent et forment..."
        titleSpacing.appendChild(subtitle)

        val subTitle3 = document.createElement("h3")
        subTitle3.textContent = "Hersonissos. Et un voyage rhéto."
        titleSpacing.appendChild(subTitle3)

        val hbox = document.createElement("div")
        hbox.className = "hbox"
        /*
        * images
        * évènements
        * actualités
        * mini-entreprises LJE
        * ezv...
         */
        val pictures = document.createElement("a") as HTMLAnchorElement
        pictures.textContent = "Galerie"
        pictures.setAttribute("href", "./html/pictures")
        hbox.appendChild(pictures)

        val events = document.createElement("a") as HTMLAnchorElement
        events.textContent = "Évènements"
        events.setAttribute("href", "html/events")
        hbox.appendChild(events)

        val news = document.createElement("a") as HTMLAnchorElement
        news.textContent = "Actualités"
        news.setAttribute("href", "html/news")
        hbox.appendChild(news)

        val lje = document.createElement("a") as HTMLAnchorElement
        lje.textContent = "Nos mini-entreprises"
        lje.setAttribute("href", "html/lje")
        hbox.appendChild(lje)

        val paragraph = document.createElement("p")
        paragraph.textContent = """
            Cette année, nous, rhétos de 2026-2027, partons vers Hersonissos, en Crête(Grèce). Ce voyage nous apprendra une multitude de choses,
            aussi bien sur le plan culturel que social. Mais un voyage aussi loin et pour une destination de rêve, ça doit coûter cher,
            n'est-ce pas ?
        """.trimIndent()

        val paragraph2 = document.createElement("p")
        paragraph2.textContent = """
            Car en effet, 600€ pour un voyage n'est pas anodin. Mais heureusement, nous pourrons compter sur:
        """.trimIndent()

        val comityParagraph = document.createElement("div")
        comityParagraph.className = "list-element-home"

        val comityTitle = document.createElement("h4")
        comityTitle.className = "comity-title"
        comityTitle.textContent = "Notre comité rhéto"
        comityParagraph.appendChild(comityTitle)

        val comityDescription = document.createElement("p")
        comityDescription.textContent = """
            Notre comité rhéto, qui organisera au fil de l'année tout les évènements visant à diminuer le prix du voyage
        """.trimIndent()
        comityParagraph.appendChild(comityDescription)

        val comityButton = document.createElement("a") as HTMLAnchorElement
        comityButton.textContent = "Qui sont-ils ?"
        comityButton.href = "/Rhetos2627-web/html/comity"
        comityParagraph.appendChild(comityButton)

        val aboutDiv = document.createElement("footer")
        aboutDiv.className = "about-div"

        val titleFooter = document.createElement("h3")
        titleFooter.textContent = "Rhétos 26-27"
        aboutDiv.appendChild(titleFooter)

        main.appendChild(titleSpacing)
        main.appendChild(hbox)
        main.appendChild(paragraph)
        main.appendChild(paragraph2)
        main.appendChild(comityParagraph)

        app.appendChild(main)
        app.appendChild(aboutDiv)
    }
